import 'package:flutter/material.dart';
import '../models.dart';
class ResultSheet extends StatelessWidget {
 const ResultSheet({super.key,required this.baseItem}); final Item baseItem;
 static Future<void> show(BuildContext context,Item item)=>showModalBottomSheet<void>(context:context,showDragHandle:true,isScrollControlled:true,builder:(_)=>ResultSheet(baseItem:item));
 @override Widget build(BuildContext context){final auction=baseItem.kind=='auction';final wanted=baseItem.kind=='wanted';final title=auction?'경매 정보':wanted?'구해요 게시글':'AI 상품 설명 제안';final lines=auction?['시작 가격: ${baseItem.price}','현재 상태: ${baseItem.status}','입찰 내역: 예시 데이터']:wanted?['희망 상품: ${baseItem.title}','희망 가격: ${baseItem.price}','게시글 상태: 예시 데이터']:['제안 제목: ${baseItem.title}','제안 설명: ${baseItem.subtitle}','사용자가 직접 수정할 수 있는 예시 문구입니다.'];return SafeArea(child:Padding(padding:const EdgeInsets.fromLTRB(18,0,18,20),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),Text('선택한 항목: ${baseItem.title}'),const SizedBox(height:10),for(var i=0;i<lines.length;i++)ListTile(contentPadding:EdgeInsets.zero,leading:CircleAvatar(backgroundColor:const Color(0xFFFFF1E7),child:Text('${i+1}',style:const TextStyle(color:Color(0xFFB84D00)))),title:Text(lines[i])),const SizedBox(height:6),Text('※ 화면 시연용으로 미리 정한 예시이며, 실제 AI 생성·입찰·거래 기능은 없습니다.',style:Theme.of(context).textTheme.bodySmall?.copyWith(color:Colors.grey)),Align(alignment:Alignment.centerRight,child:TextButton(onPressed:()=>Navigator.pop(context),child:const Text('닫기')))])));}
}
